def _windows_start_token(pid: int, kernel32: _WindowsKernel32 | None = None) -> str | None:
    try:
        import ctypes
        from ctypes import wintypes

        try:
            selected = _windows_library("kernel32") if kernel32 is None else kernel32
        except OSError as exc:
            raise OSError(
                f"Windows API access is unavailable while checking process identity for PID {pid}"
            ) from exc
        try:
            open_process = selected.OpenProcess
        except AttributeError as exc:
            raise OSError(
                f"Windows API access is unavailable for OpenProcess while checking process identity for PID {pid}"
            ) from exc
        if kernel32 is None:
            open_process.argtypes = (wintypes.DWORD, wintypes.BOOL, wintypes.DWORD)
            open_process.restype = wintypes.HANDLE
        handle = open_process(0x0400, False, pid)
        if not handle:
            try:
                error = int(selected.GetLastError())
            except AttributeError as exc:
                raise OSError(
                    f"Windows API access is unavailable for GetLastError while checking process identity for PID {pid}"
                ) from exc
            if error in (87, 1168):
                return None
            raise ProcessIdentityUnavailable(
                f"Cannot check process identity for PID {pid}; Windows error {error}"
            )
        creation = wintypes.FILETIME()
        exit_time = wintypes.FILETIME()
        kernel = wintypes.FILETIME()
        user = wintypes.FILETIME()
        exit_code = wintypes.DWORD()
        try:
            try:
                get_exit_code_process = selected.GetExitCodeProcess
            except AttributeError as exc:
                raise OSError(
                    f"Windows API access is unavailable for GetExitCodeProcess while checking process identity for PID {pid}"
                ) from exc
            if not get_exit_code_process(handle, ctypes.byref(exit_code)):
                try:
                    error = int(selected.GetLastError())
                except AttributeError as exc:
                    raise OSError(
                        f"Windows API access is unavailable for GetLastError while checking process identity for PID {pid}"
                    ) from exc
                raise ProcessIdentityUnavailable(
                    f"Cannot check process liveness for PID {pid}; Windows error {error}"
                )
            if exit_code.value != 259:
                return None
            try:
                get_process_times = selected.GetProcessTimes
            except AttributeError as exc:
                raise OSError(
                    f"Windows API access is unavailable for GetProcessTimes while checking process identity for PID {pid}"
                ) from exc
            if not get_process_times(
                handle,
                ctypes.byref(creation),
                ctypes.byref(exit_time),
                ctypes.byref(kernel),
                ctypes.byref(user),
            ):
                try:
                    error = int(selected.GetLastError())
                except AttributeError as exc:
                    raise OSError(
                        f"Windows API access is unavailable for GetLastError while checking process identity for PID {pid}"
                    ) from exc
                raise ProcessIdentityUnavailable(
                    f"Cannot read process birth time for PID {pid}; Windows error {error}"
                )
            return f"win:{creation.dwHighDateTime:08x}{creation.dwLowDateTime:08x}"
        finally:
            try:
                close_handle = selected.CloseHandle
            except AttributeError as exc:
                raise OSError(
                    f"Windows API access is unavailable for CloseHandle while checking process identity for PID {pid}"
                ) from exc
            close_handle(handle)
    except ProcessIdentityUnavailable:
        raise
